CREATE TABLE default.sales_daily\n(\n    `sale_date` Date,\n    `category_id` UInt32,\n    `category_name` String,\n    `branch_id` UInt32,\n    `branch_name` String,\n    `city` String,\n    `total_orders` UInt32,\n    `total_revenue` Float64,\n    `avg_order_value` Float64,\n    `unique_customers` UInt32,\n    `created_at` DateTime DEFAULT now()\n)\nENGINE = MergeTree\nORDER BY (sale_date, category_id, branch_id)\nSETTINGS index_granularity = 8192
